public String format(LoggingEvent event) {
    StringBuilder sb = new StringBuilder();
    String message = event.getMessage();
    String[] args = event.getArguments();
    int currentArg = 0;
    for (int i = 0; i < message.length(); i++) {
        char c = message.charAt(i);
        if (c == '%') {
            i++;
            if (i == message.length()) {
                throw new IllegalArgumentException("Incomplete conversion pattern.");
            }
            c = message.charAt(i);
            if (c == '%') {
                sb.append('%');
            } else {
                if (currentArg >= args.length) {
                    throw new IllegalArgumentException("Missing argument for conversion pattern.");
                }
                String arg = args[currentArg++];
                if (c == 's') {
                    sb.append(arg);
                } else if (c == 'd') {
                    try {
