public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int numVertices = target.vertices();
    int degree = target.degrees().stream().mapToInt(d -> d).sum();
    int numPartitions = Math.ceil(Math.sqrt(numVertices));
    int partitionSize = numVertices / numPartitions;
    List<V> vertices1 = new ArrayList<>();
    List<V> vertices2 = new ArrayList<>();
    for (int i = 0; i < numPartitions; i++) {
        int vertexId1 = i * partitionSize;
        int vertexId2 = (i + 1) * partitionSize - 1;
        V vertex1 = resultMap.get(vertexId1);
        V vertex2 = resultMap.get(vertexId2);
        vertices1.add(vertex1);
        vertices2.add(vertex2);
        for (int j = 0; j < numPartitions; j++) {
            V vertex3 = resultMap.get(j * partitionSize);
            E edge = new Edge(vertex1, vertex3, degree);
            target.addEdge(edge);
            edge = new Edge(vertex2, vertex3, degree);
            target.addEdge(edge);
        }
    }
}
```
